/**
 * Pure functions of the rule precision ledger: finding extraction, seeded
 * sampling, verdict merge, validation and the generated summary.
 */

const VERDICTS = new Set(["real", "noise", "unsure"]);
const SUMMARY_HEADER =
  "<!-- Generated by `node scripts/rule-precision.mjs summary`. Do not edit. -->";

const Z_95 = 1.959964;

/**
 * Turns a JSON report key such as `unused_dependencies` into a rule id such as
 * `unused-dependency`.
 */
export const ruleIdFromKey = (key) => {
  const kebab = key.replace(/_/g, "-");
  if (kebab.endsWith("ies")) return `${kebab.slice(0, -3)}y`;
  if (kebab.endsWith("ases")) return kebab.slice(0, -2);
  if (kebab.endsWith("s")) return kebab.slice(0, -1);
  return kebab;
};

const isFinding = (item) =>
  item !== null &&
  typeof item === "object" &&
  !Array.isArray(item) &&
  typeof item.finding_id === "string";

// A finding ID has the form `<scheme>:<rule>:<subject>` (see
// `crates/types/src/identity.rs`), so it names the rule of each finding. One
// report array can hold more than one rule, for example a stale suppression
// and a suppression with a missing reason.
const ruleOf = (finding, key) => {
  const parts = finding.finding_id.split(":");
  return parts.length >= 3 && parts[1] ? parts[1] : ruleIdFromKey(key);
};

/**
 * Groups the findings of one JSON report by rule id. Each object with a
 * `finding_id` in a top-level array is a finding. Other keys are metadata.
 */
export const findingsByRule = (report) => {
  const out = new Map();
  for (const [key, value] of Object.entries(report)) {
    if (!Array.isArray(value)) continue;
    for (const finding of value.filter(isFinding)) {
      const rule = ruleOf(finding, key);
      out.set(rule, [...(out.get(rule) ?? []), finding]);
    }
  }
  return out;
};

const PATH_FIELDS = ["path", "from_path", "file"];
const LOCATION_LISTS = [
  "imported_from",
  "used_in",
  "locations",
  "edges",
  "hops",
  "files",
  "sites",
  "members",
];

const firstPath = (finding) => {
  const field = PATH_FIELDS.find((key) => typeof finding[key] === "string");
  if (field) return { path: finding[field], line: finding.line ?? null };
  for (const key of LOCATION_LISTS) {
    const list = finding[key];
    if (!Array.isArray(list) || list.length === 0) continue;
    const first = list[0];
    if (typeof first === "string") return { path: first, line: finding.line ?? null };
    if (first && typeof first.path === "string")
      return { path: first.path, line: first.line ?? null };
  }
  return { path: null, line: null };
};

/** Returns the file and line that a reviewer opens first for a finding. */
export const findingAnchor = (finding) => firstPath(finding);

/** Removes the fields that do not help a reviewer judge a finding. */
export const reviewView = (finding) => {
  const {
    actions: _actions,
    introduced: _introduced,
    effective_severity: _severity,
    ...rest
  } = finding;
  return rest;
};

const hashSeed = (text) => {
  let h = 2166136261;
  for (let i = 0; i < text.length; i += 1) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
};

const mulberry32 = (seed) => {
  let a = seed;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
};

/**
 * Takes a deterministic sample of at most `size` findings. The same seed text
 * and the same findings give the same sample. The input order does not matter.
 */
export const seededSample = (findings, size, seedText) => {
  const sorted = findings.toSorted((a, b) => a.finding_id.localeCompare(b.finding_id));
  const random = mulberry32(hashSeed(seedText));
  for (let i = sorted.length - 1; i > 0; i -= 1) {
    const j = Math.floor(random() * (i + 1));
    [sorted[i], sorted[j]] = [sorted[j], sorted[i]];
  }
  return sorted.slice(0, size);
};

/**
 * Estimates the precision of a rule over the whole corpus.
 *
 * Each project is a stratum with its own sampling rate, so the estimate
 * weights each project's precision by its count of findings. The interval is
 * a normal interval on the stratified variance. It has no finite population
 * correction, because the ledger describes the rule on code in general, not on
 * the corpus alone. Like the Agresti-Coull interval, the range centres on the
 * adjusted proportion `(real + 2) / (judged + 4)` of each stratum, so a small
 * stratum with all-real or all-noise verdicts still adds width. Returns percentages, or `null` when no finding has a real or
 * noise verdict.
 */
export const stratifiedPrecision = (projects) => {
  const strata = projects.filter((p) => p.real + p.noise > 0);
  const total = strata.reduce((sum, p) => sum + p.findings, 0);
  if (total === 0) return null;
  let estimate = 0;
  let centre = 0;
  let variance = 0;
  for (const p of strata) {
    const judged = p.real + p.noise;
    const weight = p.findings / total;
    const adjusted = (p.real + 2) / (judged + 4);
    estimate += weight * (p.real / judged);
    centre += weight * adjusted;
    variance += weight * weight * ((adjusted * (1 - adjusted)) / judged);
  }
  const half = Z_95 * Math.sqrt(variance);
  const clamp = (x) => Math.round(Math.min(1, Math.max(0, x)) * 100);
  // The adjusted centre can pull the range off a weighted 0 or 100 percent;
  // the range always keeps the estimate itself.
  return {
    estimate: clamp(estimate),
    low: clamp(Math.min(estimate, centre - half)),
    high: clamp(Math.max(estimate, centre + half)),
  };
};

/** Sums the project counts of a ledger row. */
const rowTotals = (row) => {
  const totals = { findings: 0, sampled: 0, real: 0, noise: 0, unsure: 0 };
  for (const project of row.projects) {
    for (const key of Object.keys(totals)) totals[key] += project[key];
  }
  return totals;
};

const precisionText = (projects) => {
  const result = stratifiedPrecision(projects);
  return result ? `${result.estimate}% (${result.low} to ${result.high})` : "n/a";
};

/**
 * Builds a ledger row from a sample manifest and the verdicts of a reviewer.
 * Returns `{ ok: false, errors }` when a sampled finding has no verdict, has
 * two verdicts, or has an unknown verdict.
 */
// Returns the errors of one verdict entry. A noise verdict must name its
// cause, because the noise classes are the actionable part of a row.
const verdictEntryErrors = (entry) => {
  if (entry === null || typeof entry !== "object") return ["a verdict entry is not an object"];
  const where = `${entry.project} ${entry.id}`;
  if (typeof entry.project !== "string" || typeof entry.id !== "string") {
    return [`${where}: a verdict needs a project and an id`];
  }
  if (!VERDICTS.has(entry.verdict)) return [`${where}: unknown verdict "${entry.verdict}"`];
  if (entry.verdict === "noise" && !(typeof entry.class === "string" && entry.class.trim())) {
    return [`${where}: a noise verdict needs a class`];
  }
  return [];
};

const reviewShapeErrors = (review, label) =>
  review && Array.isArray(review.verdicts)
    ? review.verdicts.flatMap(verdictEntryErrors)
    : [`${label} has no verdicts array`];

const sampleErrors = (sample) => {
  if (!sample || !Array.isArray(sample.projects)) return ["the sample has no projects array"];
  const names = sample.projects.map((p) => p.project);
  const errors = names
    .filter((name, i) => names.indexOf(name) !== i)
    .map((name) => `the sample lists project ${name} twice`);
  for (const p of sample.projects) {
    if (!Array.isArray(p.sampled_ids) || !Number.isInteger(p.findings)) {
      errors.push(`the sample entry of ${p.project} needs sampled_ids and findings`);
    }
  }
  return errors;
};

export const buildRow = ({ sample, verdicts, reviews = 1, agreement = null }) => {
  const errors = [...sampleErrors(sample), ...reviewShapeErrors(verdicts, "the verdict file")];
  if (errors.length > 0) return { ok: false, errors };
  const byKey = new Map();
  for (const entry of verdicts.verdicts) {
    const key = `${entry.project}\0${entry.id}`;
    if (byKey.has(key)) errors.push(`${entry.project} ${entry.id}: two verdicts`);
    byKey.set(key, entry);
  }
  const classes = new Map();
  const projects = sample.projects.map((project) => {
    const counts = { real: 0, noise: 0, unsure: 0 };
    for (const id of project.sampled_ids) {
      const key = `${project.project}\0${id}`;
      const entry = byKey.get(key);
      if (!entry) {
        errors.push(`${project.project} ${id}: no verdict`);
        continue;
      }
      byKey.delete(key);
      counts[entry.verdict] += 1;
      if (entry.verdict === "noise") {
        classes.set(entry.class, (classes.get(entry.class) ?? 0) + 1);
      }
    }
    return {
      project: project.project,
      commit: project.commit,
      findings: project.findings,
      sampled: project.sampled_ids.length,
      ...counts,
    };
  });
  for (const key of byKey.keys()) errors.push(`${key.replace("\0", " ")}: not in the sample`);
  if (errors.length > 0) return { ok: false, errors };
  return {
    ok: true,
    row: {
      rule: sample.rule,
      command: sample.command,
      fallow_version: sample.fallow_version,
      reviewed_on: verdicts.reviewed_on,
      sample_size: sample.sample_size,
      reviews,
      agreement_percent: agreement,
      projects,
      noise_classes: [...classes]
        .map(([name, count]) => ({ class: name, count }))
        .toSorted((a, b) => b.count - a.count || a.class.localeCompare(b.class)),
    },
  };
};

const verdictKey = (entry) => `${entry.project}\0${entry.id}`;

const majority = (entries) => {
  const tally = new Map();
  for (const entry of entries) tally.set(entry.verdict, (tally.get(entry.verdict) ?? 0) + 1);
  const [verdict, count] = [...tally].toSorted((a, b) => b[1] - a[1])[0];
  return count * 2 > entries.length ? verdict : "unsure";
};

const indexReviews = (reviews, errors) => {
  const byKey = new Map();
  reviews.forEach((review, index) => {
    for (const entry of review.verdicts) {
      const entries = byKey.get(verdictKey(entry)) ?? [];
      if (entries[index]) {
        errors.push(`${entry.project} ${entry.id}: two verdicts in review ${index + 1}`);
      }
      entries[index] = entry;
      byKey.set(verdictKey(entry), entries);
    }
  });
  return byKey;
};

// Returns the verdict entry of one finding, or an error text.
const settleFinding = (entries) => {
  const [first, second, ...rest] = entries;
  if (!first || !second) {
    const known = entries.find(Boolean);
    return { error: `${known.project} ${known.id}: missing from one of the first two reviews` };
  }
  if (first.verdict === second.verdict) {
    return { entry: first.class || !second.class ? first : second, agreed: true };
  }
  const settling = rest.filter(Boolean);
  if (settling.length === 0) {
    return {
      error: `${first.project} ${first.id}: the first two reviews disagree and no later review settles it`,
    };
  }
  const all = [first, second, ...settling];
  const verdict = majority(all);
  const entry = all.find((e) => e.verdict === verdict && e.class) ??
    all.find((e) => e.verdict === verdict) ?? { ...first, verdict, class: undefined };
  return { entry, agreed: false };
};

/**
 * Combines independent reviews of one sample into one verdict file.
 *
 * The first two reviews cover the whole sample. A later review settles the
 * findings where the first two disagree, and may cover only those. The
 * majority verdict wins; with no majority the verdict is `unsure`. The
 * agreement is the share of findings where the first two reviews agree.
 */
export const combineReviews = (reviews) => {
  const errors = reviews.flatMap((review, i) => reviewShapeErrors(review, `review ${i + 1}`));
  if (errors.length > 0) return { ok: false, errors };
  if (reviews.length === 1) return { ok: true, verdicts: reviews[0], agreement: null, reviews: 1 };
  const settled = [...indexReviews(reviews, errors).values()].map(settleFinding);
  errors.push(...settled.filter((s) => s.error).map((s) => s.error));
  if (settled.length === 0) errors.push("the reviews have no verdicts");
  if (errors.length > 0) return { ok: false, errors };
  const agreed = settled.filter((s) => s.agreed).length;
  return {
    ok: true,
    verdicts: {
      reviewed_on: reviews
        .map((r) => r.reviewed_on)
        .toSorted()
        .at(-1),
      verdicts: settled.map((s) => s.entry),
    },
    agreement: Math.round((agreed / settled.length) * 100),
    reviews: reviews.length,
  };
};

/** Replaces the row with the same rule and command, or adds the row. */
export const upsertRow = (ledger, row) => {
  const rows = ledger.rows.filter((r) => !(r.rule === row.rule && r.command === row.command));
  rows.push(row);
  rows.sort((a, b) => a.command.localeCompare(b.command) || a.rule.localeCompare(b.rule));
  return { ...ledger, rows };
};

const COUNT_KEYS = ["findings", "sampled", "real", "noise", "unsure"];

const corpusErrors = (corpus) =>
  Object.entries(corpus).flatMap(([name, project]) => [
    ...(/^[\w.-]+\/[\w.-]+$/.test(project.repo ?? "") ? [] : [`corpus ${name}: bad repo`]),
    ...(/^[0-9a-f]{40}$/.test(project.commit ?? "")
      ? []
      : [`corpus ${name}: commit must be a full SHA`]),
  ]);

const agreementIsValid = (row) =>
  row.reviews === 1
    ? row.agreement_percent === null
    : Number.isInteger(row.agreement_percent) &&
      row.agreement_percent >= 0 &&
      row.agreement_percent <= 100;

const rowFieldErrors = (row, label) => {
  const checks = [
    [/^\d{4}-\d{2}-\d{2}$/.test(row.reviewed_on ?? ""), "bad reviewed_on"],
    [/^\d+\.\d+\.\d+/.test(row.fallow_version ?? ""), "bad fallow_version"],
    [Number.isInteger(row.reviews) && row.reviews >= 1, "reviews must be 1 or more"],
    [agreementIsValid(row), "agreement_percent must be null for one review, else 0 to 100"],
  ];
  return checks.filter(([ok]) => !ok).map(([, message]) => `${label}: ${message}`);
};

const projectErrors = (project, row, where, corpus) => {
  const pinned = corpus[project.project];
  const errors = pinned ? [] : [`${where}: project is not in the corpus`];
  if (pinned && project.commit !== pinned.commit) {
    errors.push(
      `${where}: measured at ${project.commit ?? "(no commit)"}, but the corpus pins ${pinned.commit}; measure the rule again`,
    );
  }
  if (!COUNT_KEYS.every((k) => Number.isInteger(project[k]) && project[k] >= 0)) {
    return [...errors, `${where}: counts must be integers of 0 or more`];
  }
  const checks = [
    [
      project.real + project.noise + project.unsure === project.sampled,
      "real + noise + unsure must equal sampled",
    ],
    [project.sampled <= project.findings, "sampled exceeds findings"],
    [project.sampled <= row.sample_size, "sampled exceeds sample_size"],
  ];
  return [...errors, ...checks.filter(([ok]) => !ok).map(([, message]) => `${where}: ${message}`)];
};

/** Returns the structural errors of a ledger. An empty list means valid. */
export const ledgerErrors = (ledger) => {
  if (!ledger || typeof ledger.corpus !== "object" || !Array.isArray(ledger.rows)) {
    return ["the ledger needs a corpus object and a rows array"];
  }
  const { corpus } = ledger;
  const errors = ledger.schema_version === 1 ? [] : ["schema_version must be 1"];
  errors.push(...corpusErrors(corpus));
  const seen = new Set();
  for (const row of ledger.rows ?? []) {
    const label = `${row.command} ${row.rule}`;
    if (seen.has(label)) errors.push(`${label}: duplicate row`);
    seen.add(label);
    errors.push(...rowFieldErrors(row, label));
    for (const project of row.projects ?? []) {
      errors.push(...projectErrors(project, row, `${label} ${project.project}`, corpus));
    }
  }
  return errors;
};

/** Renders the summary Markdown of a ledger. */
export const renderSummary = (ledger) => {
  const lines = [
    SUMMARY_HEADER,
    "",
    "# Rule precision",
    "",
    "Precision is the share of real findings among real and noise verdicts, from a seeded",
    "random sample of each rule's findings. Each project counts with its share of the",
    "findings, so a project with many findings weighs more than its sample. `unsure`",
    "verdicts are not in the ratio. The range is a 95 percent interval on that estimate.",
    "See `docs/rule-precision.md` for the method.",
    "Reviews is the count of independent reviews; the percentage is how often the first two agree.",
    "",
    "| Command | Rule | Findings | Sampled | Real | Noise | Unsure | Precision | Reviews | Measured on |",
    "|---|---|---|---|---|---|---|---|---|---|",
  ];
  for (const row of ledger.rows) {
    const t = rowTotals(row);
    const precision = precisionText(row.projects);
    const reviews = row.reviews === 1 ? "1" : `${row.reviews} (${row.agreement_percent}% agree)`;
    lines.push(
      `| \`${row.command}\` | \`${row.rule}\` | ${t.findings} | ${t.sampled} | ${t.real} | ${t.noise} | ${t.unsure} | ${precision} | ${reviews} | ${row.fallow_version}, ${row.reviewed_on} |`,
    );
  }
  const withNoise = ledger.rows.filter((row) => row.noise_classes.length > 0);
  if (withNoise.length > 0) {
    lines.push("", "## Noise classes", "");
    for (const row of withNoise) {
      const classes = row.noise_classes.map((c) => `${c.class} (${c.count})`).join(", ");
      lines.push(`- \`${row.rule}\`: ${classes}`);
    }
  }
  lines.push("", "## Corpus", "", "| Project | Repository | Commit |", "|---|---|---|");
  for (const [name, project] of Object.entries(ledger.corpus)) {
    lines.push(`| ${name} | ${project.repo} | \`${project.commit.slice(0, 12)}\` |`);
  }
  return `${lines.join("\n")}\n`;
};
